export async function support(width,height,fps){if(!globalThis.VideoEncoder||!globalThis.AudioEncoder||!globalThis.AudioData)throw Error('Browser ini belum menyediakan encoder frame. Gunakan paket renderer untuk MP4.');let video,audio;for(const codec of ['avc1.420033','vp09.00.10.08']){const config={codec,width,height,framerate:fps,bitrate:width>=1080?8000000:4000000,latencyMode:'quality',...(codec.startsWith('avc')?{avc:{format:'avc'}}:{})};try{if((await VideoEncoder.isConfigSupported(config)).supported){video=config;break;}}catch{}}for(const codec of ['mp4a.40.2','opus']){const config={codec,sampleRate:48000,numberOfChannels:2,bitrate:128000};try{if((await AudioEncoder.isConfigSupported(config)).supported){audio=config;break;}}catch{}}if(!video||!audio)throw Error('Encoder MP4 yang diperlukan tidak tersedia. Unduh paket renderer untuk menghasilkan MP4 lewat FFmpeg.');return{video,audio};}
export async function exportVideo(p,canvas,{width,height,fps,draw,voice,music,progress,cancelled}){const configs=await support(width,height,fps),target=new ArrayBufferTarget(),muxer=new Muxer({target,video:{codec:configs.video.codec.startsWith('avc')?'avc':'vp9',width,height,frameRate:fps},audio:{codec:configs.audio.codec==='opus'?'opus':'aac',sampleRate:48000,numberOfChannels:2},fastStart:'in-memory',firstTimestampBehavior:'offset'});let failure;const ve=new VideoEncoder({output:(chunk,meta)=>muxer.addVideoChunk(chunk,meta),error:e=>failure=e}),ae=new AudioEncoder({output:(chunk,meta)=>muxer.addAudioChunk(chunk,meta),error:e=>failure=e});const check=()=>{if(cancelled())throw Error('Ekspor dibatalkan.');if(failure)throw failure;};const frameCount=Math.ceil(total(p)*fps),duration=frameCount/fps,events=new Map();try{ve.configure(configs.video);ae.configure(configs.audio);for(let f=0;f<frameCount;f++){check();const pos=locate(p,f/fps);const sounds=await draw(pos.index,pos.local,width,height);if(!events.has(pos.index))events.set(pos.index,sounds);const frame=new VideoFrame(canvas,{timestamp:Math.round(f*1e6/fps),duration:Math.round((f+1)*1e6/fps)-Math.round(f*1e6/fps)});try{ve.encode(frame,{keyFrame:f%(fps*2)===0});}finally{frame.close();}if(ve.encodeQueueSize>6)await ve.flush();progress((f+1)/frameCount*.85,`Frame ${f+1} / ${frameCount}`);}await ve.flush();check();const ac=new OfflineAudioContext(2,Math.ceil(duration*48000),48000),master=ac.createDynamicsCompressor();master.threshold.value=-3;master.knee.value=0;master.ratio.value=20;master.connect(ac.destination);for(const [buffer,volume,loop] of [[voice,1,false],[music,p.volume??.12,true]])if(buffer){const source=ac.createBufferSource(),gain=ac.createGain();source.buffer=buffer;source.loop=loop;gain.gain.value=volume;source.connect(gain);gain.connect(master);source.start();}if(p.sfx){let offset=0;p.scenes.forEach((scene,i)=>{for(const e of events.get(i)||[])if(e.time>=0&&e.time<scene.duration)effect(ac,master,e,offset+e.time);offset+=scene.duration;});}const rendered=await ac.startRendering();for(let offset=0;offset<rendered.length;offset+=1024){check();const count=Math.min(1024,rendered.length-offset),data=new Float32Array(count*2);for(let c=0;c<2;c++)data.set(rendered.getChannelData(c).subarray(offset,offset+count),c*count);const chunk=new AudioData({format:'f32-planar',sampleRate:48000,numberOfFrames:count,numberOfChannels:2,timestamp:Math.round(offset*1e6/48000),data});try{ae.encode(chunk);}finally{chunk.close();}if(ae.encodeQueueSize>20)await ae.flush();progress(.85+.15*(offset+count)/rendered.length,'Menggabungkan suara');}await ae.flush();check();muxer.finalize();return{blob:new Blob([target.buffer],{type:'video/mp4'}),frames:frameCount,codec:configs.video.codec,audioCodec:configs.audio.codec};}finally{if(ve.state!=='closed')ve.close();if(ae.state!=='closed')ae.close();}}
